const Ins_P4 = () => {
  const context = useOutletContext();
  const resumeData = context?.ins?.data;
  return (
    <div className="summary-box">
      <h3>Distributed Settlement Ledger</h3>
      <p>{resumeData ? `Commit complete. Delay: ${resumeData.latency || 0}ms` : "[STANDBY]"}</p>
    </div>
  );
};
export default Ins_P4;
